const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage');
const ui={rings:document.getElementById('rings'),count:document.getElementById('count'),saved:document.getElementById('saved'),cap:document.getElementById('capLabel'),bar:document.getElementById('capacityBar'),toast:document.getElementById('toast'),hint:document.getElementById('hint'),intro:document.getElementById('intro'),win:document.getElementById('win'),capacityBuy:document.getElementById('capacityBuy'),speedBuy:document.getElementById('speedBuy'),dashBuy:document.getElementById('dashBuy'),capacityDesc:document.getElementById('capacityDesc')};
let W=1000,H=650,dpr=1,keys={},pressed={},running=false,last=0,toastTimer=0,shake=0;
const world={w:1700,h:1200,camera:{x:0,y:0}},player={x:850,y:590,r:17,speed:210,dir:0,dash:0,dashCd:0,anim:0};
let people=[],rings=[],saved=0,money=0,capacity=3,carried=[],speedLevel=0,dashLevel=0,capLevel=0;
const trees=[[220,180],[490,170],[760,180],[1070,170],[1420,190],[1550,400],[180,440],[400,400],[650,380],[1180,380],[1430,690],[1260,930],[880,1030],[520,960],[240,840],[1000,700],[350,680],[710,780]];
const rnd=(a,b)=>a+Math.random()*(b-a);function resize(){const r=stage.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);
function spawn(){people=[];rings=[];const colors=['#ff7896','#ffd466','#a5ef89','#b994ff','#ff9e59','#69ddff','#fa9be3','#a7d0ff'];for(let i=0;i<17;i++){let x,y,tries=0;do{x=rnd(90,world.w-90);y=rnd(90,world.h-90);tries++}while((Math.hypot(x-850,y-590)<230||trees.some(t=>Math.hypot(t[0]-x,t[1]-y)<62))&&tries<100);people.push({x,y,r:13,color:colors[i%colors.length],phase:rnd(0,6),following:false,id:i})}for(let i=0;i<42;i++){let x=rnd(80,world.w-80),y=rnd(80,world.h-80);if(Math.hypot(x-850,y-590)>125)rings.push({x,y,phase:rnd(0,6),got:false})}}
function reset(){money=0;saved=0;capacity=3;carried=[];speedLevel=0;dashLevel=0;capLevel=0;player.x=850;player.y=590;player.speed=210;player.dash=0;player.dashCd=0;spawn();updateUI();ui.win.classList.remove('show');ui.intro.classList.remove('show');running=true}
function updateUI(){ui.rings.textContent=money;ui.count.textContent=`${carried.length} / ${capacity}`;ui.saved.textContent=saved;ui.cap.textContent=`${carried.length} / ${capacity}`;ui.bar.style.width=`${Math.min(100,carried.length/capacity*100)}%`;ui.capacityBuy.textContent=`💍 ${12+capLevel*14}`;ui.speedBuy.textContent=`💍 ${10+speedLevel*12}`;ui.dashBuy.textContent=`💍 ${8+dashLevel*10}`;ui.capacityDesc.textContent=`Capacidade +2 • atual: ${capacity}`;ui.capacityBuy.disabled=money<12+capLevel*14;ui.speedBuy.disabled=money<10+speedLevel*12;ui.dashBuy.disabled=money<8+dashLevel*10}
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1750)}
function doAction(){if(!running)return;const shelter=Math.hypot(player.x-850,player.y-590)<83;if(shelter&&carried.length){const n=carried.length;saved+=n;money+=n*5;carried=[];updateUI();toast(`🏡 ${n} viajante${n>1?'s':''} chegou${n>1?'aram':'u'} em segurança! +${n*5} anéis`);if(saved>=17)setTimeout(()=>{if(running)ui.win.classList.add('show')},750);return}if(carried.length>=capacity){toast('🎒 Equipe cheia! Volte ao abrigo para deixar o grupo.');return}const nearby=people.filter(p=>!p.following&&Math.hypot(p.x-player.x,p.y-player.y)<56).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(nearby){nearby.following=true;carried.push(nearby);updateUI();toast('💙 Um viajante escolheu correr com você!');return}if(shelter){toast('🏡 O abrigo está pronto para receber seu grupo!')}else toast('🔎 Chegue mais perto de alguém para convidar!')}
function dash(){if(!running||player.dashCd>0)return;player.dash=.22;player.dashCd=Math.max(.65,1.35-dashLevel*.17);shake=5}
document.getElementById('startBtn').onclick=()=>{reset();toast('💙 A aventura começou!')};document.getElementById('againBtn').onclick=reset;document.getElementById('interactBtn').addEventListener('pointerdown',e=>{e.preventDefault();doAction()});document.getElementById('dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
ui.capacityBuy.onclick=()=>{let cost=12+capLevel*14;if(money>=cost){money-=cost;capacity+=2;capLevel++;updateUI();toast('🎒 Mais espaço para sua equipe!')}};ui.speedBuy.onclick=()=>{let cost=10+speedLevel*12;if(money>=cost){money-=cost;speedLevel++;player.speed+=24;updateUI();toast('👟 Agora você corre mais rápido!')}};ui.dashBuy.onclick=()=>{let cost=8+dashLevel*10;if(money>=cost){money-=cost;dashLevel++;updateUI();toast('💨 Impulso recarrega rapidinho!')}};
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d','e'].includes(k))e.preventDefault();if(!keys[k])pressed[k]=true;keys[k]=true;if(k==='e')doAction();if(k===' ')dash()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={}});
for(const b of document.querySelectorAll('.tc')){const dir=b.dataset.dir,kv={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[kv[dir]]=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys[kv[dir]]=false)}
function update(dt){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.dir=Math.atan2(dy,dx)}player.dash=Math.max(0,player.dash-dt);player.dashCd=Math.max(0,player.dashCd-dt);const vel=player.speed*(player.dash>0?2.45:1);player.x=Math.max(34,Math.min(world.w-34,player.x+dx*vel*dt));player.y=Math.max(34,Math.min(world.h-34,player.y+dy*vel*dt));player.anim+=dt*(len?10:2);for(let i=0;i<carried.length;i++){let p=carried[i],a=player.anim*.8-i*.8;p.x=player.x-Math.cos(player.dir)*27-Math.cos(a)*13;p.y=player.y-Math.sin(player.dir)*27+Math.sin(a)*13}
for(const r of rings){r.phase+=dt*3;if(!r.got&&Math.hypot(r.x-player.x,r.y-player.y)<27){r.got=true;money++;updateUI()}}const cam=world.camera;cam.x=Math.max(0,Math.min(world.w-W,player.x-W/2));cam.y=Math.max(0,Math.min(world.h-H,player.y-H/2));shake=Math.max(0,shake-dt*20)}
function roundRect(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawGround(){ctx.fillStyle='#82c96b';ctx.fillRect(0,0,world.w,world.h);ctx.fillStyle='#78bd63';for(let y=0;y<world.h;y+=64)for(let x=0;x<world.w;x+=64)if(((x*13+y*7)%5)<2)ctx.fillRect(x+((y/64|0)%2)*20,y,22,12);
// winding paths
ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#d9c99b';ctx.lineWidth=118;ctx.beginPath();ctx.moveTo(-30,590);ctx.bezierCurveTo(300,600,370,310,650,350);ctx.bezierCurveTo(920,390,950,700,1190,650);ctx.bezierCurveTo(1400,600,1380,350,1740,350);ctx.stroke();ctx.beginPath();ctx.moveTo(850,-40);ctx.bezierCurveTo(850,240,900,275,850,590);ctx.bezierCurveTo(800,860,960,900,970,1240);ctx.stroke();ctx.strokeStyle='#eee0b9';ctx.lineWidth=95;ctx.beginPath();ctx.moveTo(-30,590);ctx.bezierCurveTo(300,600,370,310,650,350);ctx.bezierCurveTo(920,390,950,700,1190,650);ctx.bezierCurveTo(1400,600,1380,350,1740,350);ctx.stroke();ctx.beginPath();ctx.moveTo(850,-40);ctx.bezierCurveTo(850,240,900,275,850,590);ctx.bezierCurveTo(800,860,960,900,970,1240);ctx.stroke();
// water pond
ctx.fillStyle='#45b9da';ctx.beginPath();ctx.ellipse(1380,900,148,82,-.18,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b8f1f8';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(1380,900,124,62,-.18,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#c9e8a1';ctx.beginPath();ctx.ellipse(1380,900,160,91,-.18,0,Math.PI*2);ctx.stroke();
// trees
for(const [x,y] of trees){ctx.fillStyle='#588d48';ctx.beginPath();ctx.ellipse(x+3,y+10,25,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#986d43';ctx.fillRect(x-4,y-8,8,24);ctx.fillStyle='#318e52';ctx.beginPath();ctx.arc(x,y-17,25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#49aa5c';ctx.beginPath();ctx.arc(x-9,y-23,14,0,Math.PI*2);ctx.fill();ctx.fillStyle='#72c96c';ctx.beginPath();ctx.arc(x+5,y-30,10,0,Math.PI*2);ctx.fill()}
// picnic props / flowers
for(let i=0;i<30;i++){const x=(i*173+80)%world.w,y=(i*251+120)%world.h;if(Math.hypot(x-850,y-590)>100){ctx.fillStyle=i%2?'#fff5b0':'#f8a6c5';ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill()}}
}

function drawShelter(){ctx.save();ctx.translate(850,590);ctx.fillStyle='#153a58';ctx.beginPath();ctx.ellipse(0,40,73,23,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6ce2ff';ctx.beginPath();ctx.arc(0,0,56,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e2fbff';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,56,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 30px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('🏡',0,-2);ctx.fillStyle='#073552';ctx.font='bold 12px system-ui';ctx.fillText('ABRIGO',0,37);ctx.restore()}
function drawRing(r){let s=1+Math.sin(r.phase)*.08;ctx.save();ctx.translate(r.x,r.y);ctx.scale(s,s);ctx.strokeStyle='#ffcb42';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(0,0,9,13,.28,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#fff2a1';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(-1,-1,5,9,.28,-1.8,-.4);ctx.stroke();ctx.restore()}
function drawPerson(p){ctx.save();ctx.translate(p.x,p.y+Math.sin(p.phase+player.anim)*2);ctx.fillStyle='#23445a44';ctx.beginPath();ctx.ellipse(0,12,13,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.roundRect(-9,0,18,18,7);ctx.fill();ctx.fillStyle='#ffd2ae';ctx.beginPath();ctx.arc(0,-6,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#46362e';ctx.beginPath();ctx.arc(0,-10,9,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#27394b';ctx.beginPath();ctx.arc(3,-6,1.3,0,7);ctx.fill();ctx.fillStyle='#f8fbff';ctx.beginPath();ctx.ellipse(-5,17,5,3,0,0,7);ctx.ellipse(5,17,5,3,0,0,7);ctx.fill();if(!p.following&&Math.hypot(p.x-player.x,p.y-player.y)<65){ctx.fillStyle='#fff';ctx.beginPath();ctx.roundRect(-10,-35,20,18,7);ctx.fill();ctx.fillStyle='#147de3';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText('＋',0,-22)}ctx.restore()}
function drawSonic(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.dir);if(player.dash>0){ctx.strokeStyle='#abf1ff';ctx.lineWidth=4;for(let i=0;i<5;i++){ctx.globalAlpha=.5-i*.08;ctx.beginPath();ctx.moveTo(-21-i*10,-8+i*4);ctx.lineTo(-42-i*10,-8+i*4);ctx.stroke()}ctx.globalAlpha=1}
// iconic blue quills
ctx.fillStyle='#0874d6';ctx.beginPath();ctx.moveTo(-8,-11);ctx.lineTo(-31,-22);ctx.lineTo(-23,-5);ctx.lineTo(-35,2);ctx.lineTo(-19,8);ctx.lineTo(-22,22);ctx.lineTo(-5,15);ctx.quadraticCurveTo(13,17,17,1);ctx.quadraticCurveTo(15,-12,-8,-11);ctx.fill();
ctx.fillStyle='#f3bd8b';ctx.beginPath();ctx.ellipse(3,3,12,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(8,-7,7,9,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1f4058';ctx.beginPath();ctx.ellipse(10,-6,2.1,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f1d8b8';ctx.beginPath();ctx.ellipse(12,5,8,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e5324b';ctx.beginPath();ctx.roundRect(-8,10,17,7,3);ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(-6,11,7,2);ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(8,15,8,4,0,0,7);ctx.fill();ctx.fillStyle='#e6334c';ctx.beginPath();ctx.ellipse(-9,15,8,4,0,0,7);ctx.fill();ctx.restore()}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const cam=world.camera;ctx.save();ctx.translate(-cam.x+(shake?rnd(-shake,shake):0),-cam.y+(shake?rnd(-shake,shake):0));drawGround();for(const r of rings)if(!r.got)drawRing(r);drawShelter();for(const p of people)if(!p.following)drawPerson(p);for(const p of carried)drawPerson(p);drawSonic();ctx.restore();
// mini-map
const mw=Math.min(138,W*.25),mh=mw*(world.h/world.w);ctx.globalAlpha=.9;roundRect(W-mw-12,12,mw,mh,10,'#09233bc9');ctx.globalAlpha=1;ctx.strokeStyle='#ffffff55';ctx.lineWidth=1;ctx.strokeRect(W-mw-12,12,mw,mh);ctx.fillStyle='#63ddff';ctx.beginPath();ctx.arc(W-mw-12+850/world.w*mw,12+590/world.h*mh,4,0,7);ctx.fill();ctx.fillStyle='#ffed9a';for(const p of people)if(!p.following){ctx.beginPath();ctx.arc(W-mw-12+p.x/world.w*mw,12+p.y/world.h*mh,1.5,0,7);ctx.fill()}ctx.fillStyle='#edbe42';for(const r of rings)if(!r.got){ctx.fillRect(W-mw-12+r.x/world.w*mw,12+r.y/world.h*mh,1.5,1.5)} }
function frame(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;if(running)update(dt);draw();requestAnimationFrame(frame)}
resize();spawn();updateUI();ui.intro.classList.add('show');requestAnimationFrame(frame);
</script></body></html>

