const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage');
const ui={rings:document.getElementById('rings'),count:document.getElementById('count'),saved:document.getElementById('saved'),cap:document.getElementById('capLabel'),bar:document.getElementById('capacityBar'),toast:document.getElementById('toast'),hint:document.getElementById('hint'),intro:document.getElementById('intro'),win:document.getElementById('win'),capacityBuy:document.getElementById('capacityBuy'),speedBuy:document.getElementById('speedBuy'),dashBuy:document.getElementById('dashBuy'),capacityDesc:document.getElementById('capacityDesc')};
let W=1000,H=650,dpr=1,keys={},pressed={},running=false,last=0,toastTimer=0,shake=0;
const world={w:1700,h:1200,camera:{x:0,y:0}},player={x:850,y:590,r:17,speed:210,dir:0,dash:0,dashCd:0,anim:0};let people=[],rings=[],saved=0,money=0,capacity=3,carried=[],speedLevel=0,dashLevel=0,capLevel=0;
