 function update(dt){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;sonic.dir=Math.atan2(dy,dx)}sonic.dash=Math.max(0,sonic.dash-dt);sonic.dashCd=Math.max(0,sonic.dashCd-dt);let v=sonic.speed*(sonic.dash?2.45:1);sonic.x=Math.max(30,Math.min(1670,sonic.x+dx*v*dt));sonic.y=Math.max(30,Math.min(1170,sonic.y+dy*v*dt));sonic.anim+=dt*(len?10:2);carried.forEach((p,i)=>{let a=sonic.anim*.8-i*.8;p.x=sonic.x-Math.cos(sonic.dir)*27-Math.cos(a)*13;p.y=sonic.y-Math.sin(sonic.dir)*27+Math.sin(a)*13});for(const r of rings){r.phase+=dt*3;if(!r.got&&Math.hypot(r.x-sonic.x,r.y-sonic.y)<27){r.got=true;money++;uiUpdate()}}world.camera.x=Math.max(0,Math.min(world.w-W,sonic.x-W/2));world.camera.y=Math.max(0,Math.min(world.h-H,sonic.y-H/2))}
