+function drawShelter(){const x=850,y=590;ctx.fillStyle='#17436b35';ctx.beginPath();ctx.ellipse(x,y+5,91,69,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a7f3ff';ctx.lineWidth=4;ctx.setLineDash([8,7]);ctx.beginPath();ctx.arc(x,y,79,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#d9f5ff';ctx.beginPath();ctx.moveTo(x-48,y-5);ctx.lineTo(x,y-48);ctx.lineTo(x+48,y-5);ctx.closePath();ctx.fill();rounded(x-39,y-8,78,50,9,'#f1fbff');rounded(x-11,y+12,22,30,7,'#268bd1');ctx.fillStyle='#76dfff';ctx.fillRect(x-31,y+4,13,12);ctx.fillRect(x+18,y+4,13,12);ctx.fillStyle='#153c64';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText('ABRIGO',x,y+60);ctx.textAlign='start';ctx.fillStyle='#ffdb68';ctx.beginPath();ctx.arc(x,y-18,7,0,Math.PI*2);ctx.fill()}
