;font-size:17px;touch-action:none}.tc.up{top:0;left:41px}.tc.down{bottom:0;left:41px}.tc.left{top:27px;left:0}.tc.right{top:27px;right:0}.action-btn{pointer-events:auto;border:1px solid #ffe78c;background:#ffc842;color:#352300;font-weight:1000;border-radius:50%;width:68px;height:68px;box-shadow:0 5px 0 #be8116;font-size:12px;touch-action:none}.action-btn.dash{width:55px;height:55px;margin:0 9px 5px 0;background:#52d7ff;border-color:#a6f1ff;box-shadow:0 5px 0 #178eb8}.touch-actions{display:flex;align-items:flex-end;gap:4px}.overlay{position:absolute;inset:0;background:#071b34b8;display:none;place-items:center;z-index:4;padding:20px}.overlay.show{display:grid}.modal{width:min(420px,100%);padding:26px;background:linear-gradient(150deg,#143b61,#0a1c32);border:1px solid #ffffff35;border-radius:22px;text-align:center;box-shadow:0 20px 80px #0008}.modal h2{font-size:26px;margin:0 0 9px}.modal p{font-size:13px;color:#c1d9eb;line-height:1.6}.primary{border:0;border-radius:12px;padding:12px 20px;background:#ffcf50;color:#302200;font-weight:1000;cursor:pointer;font-size:14px;box-shadow:0 4px 0 #c1881c}.footer{font-size:10px;color:#8aa8c2;text-align:center;flex-shrink:0}
