const {spawn}=require('node:child_process');
(async()=>{
 const chrome=spawn('chromium',['--headless','--no-sandbox','--disable-gpu','--remote-debugging-port=9231','--user-data-dir=/tmp/opencode/sonic-profile','file:///home/runner/work/PlayGround/PlayGround/index.html'],{stdio:'ignore'});
 try{
  let targets;
  for(let i=0;i<60;i++){
   try{targets=await fetch('http://127.0.0.1:9231/json').then(r=>r.json());if(targets.some(t=>t.type==='page'))break}catch{}
   await new Promise(r=>setTimeout(r,250));
  }
  const target=targets.find(t=>t.type==='page'); if(!target)throw Error('No browser page');
  const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});
  let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
  const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  const evalJS=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.result.value;
  await send('Runtime.enable');
  await evalJS("document.querySelector('#startBtn').click()");
  const started=await evalJS("!document.querySelector('#intro').classList.contains('show') && travelers.length===17");
  const invited=await evalJS("sonic.x=travelers[0].x;sonic.y=travelers[0].y;action();carried.length");
  const delivered=await evalJS("sonic.x=850;sonic.y=590;action();saved");
  const upgrade=await evalJS("money=50;uiUpdate();document.querySelector('#capacityBuy').click();[capacity,money]");
  console.log(JSON.stringify({started,invited,delivered,upgrade}));
  ws.close();if(!started||invited!==1||delivered!==1||upgrade[0]!==5||upgrade[1]!==38)process.exitCode=1;
 }finally{chrome.kill('SIGTERM')}
})().catch(e=>{console.error(e);process.exit(1)});
EOF
